import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

public class F {
    BufferedReader br;
    PrintWriter out;
    String INPUT = "";

    void solve() throws IOException {
        int n = ni(), K = ni();
        int[][] ts = new int[K][];
        long all = 0;
        for (int i = 0; i < K; i++) {
            ts[i] = na(2);
            all += ts[i][1] - ts[i][0];
        }
        int[] dpe = new int[n + 1];
        int[] dpo = new int[n + 1];
        Arrays.fill(dpe, 99999999);
        Arrays.fill(dpo, 99999999);
        if (ts[0][0] > n) {
            out.println("Hungry");
            return;
        }
        dpe[ts[0][0]] = 0;
        for (int i = 0; i < K; i++) {
            int[] ndpo = new int[n + 1];
            int[] ndpe = new int[n + 1];
            Arrays.fill(ndpo, 99999999);
            Arrays.fill(ndpe, 99999999);
            Deque<Integer> dq = new ArrayDeque<>();
            int w = ts[i][1] - ts[i][0];
            for (int j = 0; j <= n; j++) {
                while (dq.size() > 0 && dpe[dq.peekLast()] >= dpe[j]) {
                    dq.pollLast();
                }
                while (dq.size() > 0 && dq.peekFirst() < j - w) {
                    dq.pollFirst();
                }
                dq.add(j);
                ndpo[j] = Math.min(ndpo[j], dpe[dq.peekFirst()] + 1);
                if (j + w <= n) ndpe[j + w] = Math.min(ndpe[j + w], dpe[j]);
            }
            dq.clear();
            for (int j = 0; j <= n; j++) {
                while (dq.size() > 0 && dpo[dq.peekLast()] >= dpo[j]) {
                    dq.pollLast();
                }
                while (dq.size() > 0 && dq.peekFirst() < j - w) {
                    dq.pollFirst();
                }
                dq.add(j);
                ndpe[j] = Math.min(ndpe[j], dpo[dq.peekFirst()] + 1);
                ndpo[j] = Math.min(ndpo[j], dpo[j]);
            }
            dpo = ndpo;
            dpe = ndpe;

            for (int j = 0; j <= n; j++) {
                dpe[j] = Math.min(dpe[j], dpo[j] + 1);
                dpo[j] = Math.min(dpo[j], dpe[j] + 1);
            }

            int s = (i == K - 1 ? 2 * n : ts[i + 1][0]) - ts[i][1];
            for (int j = n; j >= s; j--) {
                dpe[j] = dpe[j - s];
            }
            for (int j = Math.min(n, s - 1); j >= 0; j--) dpe[j] = 99999999;
        }
        int ans = Math.min(dpe[n], dpo[n]);
        if (ans >= 9999999) {
            out.println("Hungry");
        } else {
            out.println("Full");
            out.println(ans);
        }
    }

    void run() throws Exception {
        if (oj) {
            br = new BufferedReader(new InputStreamReader(System.in));
        } else {
            br = new BufferedReader(new InputStreamReader(new ByteArrayInputStream(INPUT.getBytes())));
        }
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        tr(System.currentTimeMillis() - s + "ms");
    }

    public static void main(String[] args) throws Exception {
        new F().run();
    }

    private StringTokenizer st;
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private int ni() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private long nl() throws IOException {
        return Long.parseLong(nextToken());
    }

    private double nd() throws IOException {
        return Double.parseDouble(nextToken());
    }

    private String ns() throws IOException {
        return nextToken();
    }

    private int[] na(int n) throws IOException {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = ni();
        return a;
    }

    private char[] ns(int n) throws IOException {
        char[] buf = new char[n];
        int p = 0;
        String s = ns();
        for (int i = 0; i < n && i < s.length(); i++) buf[p++] = s.charAt(i);
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m) throws IOException {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) map[i] = ns(m);
        return map;
    }

    private boolean oj = System.getProperty("ONLINE_JUDGE") != null;
    private void tr(Object... o) {
        if (!oj) System.out.println(Arrays.deepToString(o));
    }
}
